window.compassionCareServices=[{"title": "Ambulatory transportation", "key": "ambulatory", "slug": "ambulatory-transportation", "summary": "Transportation for passengers who walk independently or use a cane or walker.", "detail": "Share any walking aids, steps or boarding assistance needs when requesting a ride. The team can then confirm whether the vehicle and available support fit your trip.", "question": "Can I travel with a cane or walker?", "answer": "Tell the team which mobility aid you use and what assistance you need so they can confirm a suitable ride."}, {"title": "Wheelchair transportation", "key": "wheelchair", "slug": "wheelchair-transportation", "summary": "Accessible transportation arranged around your wheelchair and assistance needs.", "detail": "Include your wheelchair type, pickup access and any assistance requirements. The team must confirm vehicle compatibility and pickup arrangements before accepting the ride.", "question": "What details are needed for wheelchair transportation?", "answer": "Share your wheelchair type, pickup and destination addresses, appointment time and access conditions so the team can check suitability."}, {"title": "Hospital discharges", "key": "hospital", "slug": "hospital-discharges", "summary": "Transportation from the hospital to home or an agreed care destination.", "detail": "Coordinate your request with the discharge team. Share the expected ready time, destination, mobility needs and contact person; discharge readiness and ride availability must be confirmed.", "question": "Can a family member arrange a discharge ride?", "answer": "A family member or facility coordinator can request transportation and provide the pickup, destination and assistance details for review."}, {"title": "Doctor appointments", "key": "doctor", "slug": "doctor-appointments", "summary": "Non-emergency rides to scheduled medical visits and outpatient appointments.", "detail": "Provide the time you need to arrive, not just the appointment start time. Discuss return transportation and any companion or mobility needs when requesting your trip.", "question": "What time should I request pickup?", "answer": "Share your required arrival time and both addresses. The team can review travel time and boarding needs before confirming pickup."}, {"title": "Dialysis transportation", "key": "dialysis", "slug": "dialysis-transportation", "summary": "Transportation requests for dialysis visits, including recurring appointment schedules.", "detail": "Share treatment days, arrival times and expected return arrangements. Each recurring schedule needs team confirmation; changes in appointment times or assistance needs should be communicated.", "question": "Can I request recurring dialysis rides?", "answer": "Yes. Provide your appointment pattern and transportation requirements so the team can review a recurring schedule and confirm availability."}, {"title": "Rehabilitation appointments", "key": "rehabilitation", "slug": "rehabilitation-appointments", "summary": "Rides to physical therapy, rehabilitation and other scheduled recovery appointments.", "detail": "Let the team know about walking aids, boarding needs and changes in mobility. Transportation supports getting to appointments; therapy and treatment remain with your healthcare professionals.", "question": "Can transportation be arranged for repeated therapy visits?", "answer": "Provide the dates, required arrival times and mobility needs so the team can review your schedule and suitable transportation."}, {"title": "Assisted living and nursing facility transportation", "key": "facility", "slug": "facility-transportation", "summary": "Coordinated transportation for assisted living and nursing facility residents.", "detail": "Facility staff or families can share resident transportation needs, pickup access, appointment details and the receiving contact. Confirm handoff responsibilities and return arrangements with the team.", "question": "Can a facility coordinate transportation for a resident?", "answer": "Yes. A facility coordinator can provide trip details and assistance needs for the transportation team to review."}];